using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
internal class CommandScript : IRunCommand {
 public void Execute(ExecutionResult result) {
  var cs=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<ComputeShader>("Packages/com.vivid.render-pipelines/Editor/Tools/VSMDepthLayerValidation.compute"));
  var mat=new Material(AssetDatabase.LoadAssetAtPath<Shader>("Packages/com.vivid.render-pipelines/Editor/Tools/VSMDepthLayerValidation.shader"));
  var desc=new RenderTextureDescriptor(16,16,GraphicsFormat.R32_UInt,0){enableRandomWrite=true,dimension=TextureDimension.Tex2DArray,volumeDepth=8};
  var s=new RenderTexture(desc);var d=new RenderTexture(desc);s.Create();d.Create();
  var z=new RenderTexture(new RenderTextureDescriptor(16,16,GraphicsFormat.None,32));z.Create();
  var cmd=new CommandBuffer();string report="";using var hits=new GraphicsBuffer(GraphicsBuffer.Target.Structured,256,4);
  try {
   for(int test=0;test<3;test++) {
    cmd.Clear();int clear=cs.FindKernel("Clear");cmd.SetComputeTextureParam(cs,clear,"_Static",s);cmd.SetComputeTextureParam(cs,clear,"_Dynamic",d);cmd.DispatchCompute(cs,clear,2,2,8);
    cmd.SetRenderTarget(z);cmd.ClearRenderTarget(true,false,Color.clear);cmd.SetViewport(new Rect(0,0,16,16));cmd.SetRandomWriteTarget(0,s);cmd.SetGlobalInt("_Order",test);
    cmd.DrawProcedural(Matrix4x4.identity,mat,0,MeshTopology.Triangles,3,1024);cmd.ClearRandomWriteTargets();Graphics.ExecuteCommandBuffer(cmd);
    var read=AsyncGPUReadback.Request(s);read.WaitForCompletion();if(read.hasError)throw new Exception("readback");var data=read.GetData<uint>();
    for(int layer=0;layer<8;layer++)for(int i=0;i<256;i++) {float expected=(16-layer)/32f;if(read.GetData<uint>(layer)[i]!=Unity.Mathematics.math.asuint(expected))throw new Exception("Raster insertion failed "+test+" layer="+layer+" actual="+Unity.Mathematics.math.asfloat(read.GetData<uint>(layer)[i]));}
    report+="raster order="+test+" 1024 overlapping fragments/pixel sorted distinct top8 pass\n";
   }
   // Dynamic pool contains a deeper, independently ranked surface. Its hit
   // must survive even when every corresponding static rank is in front.
   cmd.Clear();cmd.SetRenderTarget(z);cmd.ClearRenderTarget(true,false,Color.clear);cmd.SetRandomWriteTarget(0,d);cmd.SetGlobalInt("_Order",0);cmd.DrawProcedural(Matrix4x4.identity,mat,0,MeshTopology.Triangles,3,2);cmd.ClearRandomWriteTargets();
   int merge=cs.FindKernel("Merge");cmd.SetComputeTextureParam(cs,merge,"_Static",s);cmd.SetComputeTextureParam(cs,merge,"_Dynamic",d);cmd.SetComputeBufferParam(cs,merge,"_Hits",hits);cmd.DispatchCompute(cs,merge,2,2,1);Graphics.ExecuteCommandBuffer(cmd);
   var hd=new uint[256];hits.GetData(hd);foreach(uint h in hd)if(h!=1)throw new Exception("static/dynamic merge failed");report+="independent static/dynamic hidden intersection pass\n";
   for(int dirty=0;dirty<2;dirty++) {
    cmd.Clear();int k=cs.FindKernel("ClearCached");cmd.SetComputeIntParam(cs,"_Dirty",dirty);cmd.SetComputeTextureParam(cs,k,"_Static",s);cmd.SetComputeTextureParam(cs,k,"_Dynamic",d);cmd.DispatchCompute(cs,k,2,2,8);Graphics.ExecuteCommandBuffer(cmd);
    foreach(var pool in new[]{s,d}) {var r=AsyncGPUReadback.Request(pool);r.WaitForCompletion();if(r.hasError)throw new Exception("clear readback");var data=r.GetData<uint>();for(int layer=0;layer<8;layer++)for(int i=0;i<data.Length;i++) {bool zero=pool==d||dirty==1;if((r.GetData<uint>(layer)[i]==0)!=zero)throw new Exception("cache clear failed");}}
    report+="cache dirty="+dirty+" all8 layers pass\n";
   }
   File.WriteAllText("Packages/VividRP/Temp~/vsm-backfaces/raster-validation.txt",report);result.Log(report);
  } finally {cmd.Dispose();UnityEngine.Object.DestroyImmediate(cs);UnityEngine.Object.DestroyImmediate(mat);UnityEngine.Object.DestroyImmediate(s);UnityEngine.Object.DestroyImmediate(d);UnityEngine.Object.DestroyImmediate(z);}
 }
